function ticketPreview() {
    const el = $("ticketPreviewHint");
    if (!el) return;
    const now = new Date;
    const roman = typeof ROMAN_MONTH !== "undefined" ? ROMAN_MONTH[now.getMonth()] : "VII";
    const year = now.getFullYear();
    const sub = t => String(t || "").replace(/\{BULAN\}/g, roman).replace(/\{TAHUN\}/g, year);
    const sv = sub($("brTicketSvc") && $("brTicketSvc").value || "RL/STTS/{BULAN}/{TAHUN}");
    const wr = sub($("brTicketWr") && $("brTicketWr").value || "STTS/{BULAN}/{TAHUN}");
    el.innerHTML = "Contoh: Service <b>0001/" + esc(sv) + "</b> • Garansi <b>0001/" + esc(wr) + "</b>. {BULAN}=bulan Romawi (Juli=VII), {TAHUN}=tahun, otomatis. Nomor depan diisi manual saat tambah laporan.";
}

function csvCell(v) {
    v = v == null ? "" : String(v);
    return '"' + v.replace(/"/g, '""') + '"';
}

function exportCsv() {
    if (!isOwner()) {
        toast("Aksi tidak tersedia.", "error");
        return;
    }
    const head = [ "Tiket", "Masuk", "Diambil", "Jenis Servis", "Device", "Merek", "Customer", "WhatsApp", "Level", "Status", "Biaya", "Modal", "Laba", "Pembayaran", "Garansi(hari)", "Pekerjaan" ];
    const lines = [ head.map(csvCell).join(",") ];
    const _src = typeof finRows === "function" ? finRows() : reports;
    _src.forEach(r => {
        const laba = (Number(r.fee) || 0) - (Number(r.cost) || 0);
        lines.push([ r.ticket_no, (r.date_in || "").slice(0, 10), (r.date_out || "").slice(0, 10), r.job_type || "Service", r.device, r.brand, r.customer, r.customer_phone, "L" + r.level, r.status, Number(r.fee) || 0, Number(r.cost) || 0, laba, r.payment_status, r.warranty_days || 0, (r.tasks || "").replace(/\n/g, " ") ].map(csvCell).join(","));
    });
    const blob = new Blob([ "\ufeff" + lines.join("\n") ], {
        type: "text/csv;charset=utf-8;"
    });
    const a = document.createElement("a");
    a.href = URL.createObjectURL(blob);
    a.download = "laporan-servis-" + (typeof _finMonth !== "undefined" && _finMonth ? _finMonth : "semua") + "-" + (new Date).toISOString().slice(0, 10) + ".csv";
    a.click();
    URL.revokeObjectURL(a.href);
}

