let _modalHist = false;

function anyModalOpen() {
    return !!document.querySelector(".modal-bg.open");
}

function openModal(id) {
    document.querySelectorAll(".modal-bg.open").forEach(m => {
        if (m.id !== id) m.classList.remove("open");
    });
    const el = document.getElementById(id);
    if (el) el.classList.add("open");
    if (!_modalHist) {
        try {
            history.pushState({
                rlModal: 1
            }, "");
        } catch (e) {}
        _modalHist = true;
    }
    try {
        applyLang();
    } catch (e) {}
}

function closeModal(id) {
    if (id === "camModal") {
        try {
            stopCamStream();
        } catch (e) {}
    }
    const el = document.getElementById(id);
    if (el) el.classList.remove("open");
    if (_modalHist && !anyModalOpen()) {
        _modalHist = false;
        try {
            history.back();
        } catch (e) {}
    }
}

function closeAllModals() {
    const was = anyModalOpen();
    document.querySelectorAll(".modal-bg.open").forEach(m => m.classList.remove("open"));
    if (was && _modalHist) {
        _modalHist = false;
        try {
            history.back();
        } catch (e) {}
    }
}

window.addEventListener("popstate", () => {
    if ($("camModal") && $("camModal").classList.contains("open")) {
        try {
            history.pushState({
                rlModal: 1
            }, "");
        } catch (e) {}
        closeCamera();
        return;
    }
    if ($("formModal").classList.contains("open") && formDirty) {
        try {
            history.pushState({
                rlModal: 1
            }, "");
        } catch (e) {}
        requestCloseModal("formModal");
        return;
    }
    if (anyModalOpen()) {
        document.querySelectorAll(".modal-bg.open").forEach(m => m.classList.remove("open"));
        _modalHist = false;
    }
});

document.querySelectorAll(".modal-bg").forEach(bg => bg.addEventListener("click", e => {
    if (e.target === bg) requestCloseModal(bg.id);
}));

function toast(msg, type) {
    let c = document.getElementById("toastWrap");
    if (!c) {
        c = document.createElement("div");
        c.id = "toastWrap";
        c.style.cssText = "position:fixed;left:50%;bottom:24px;transform:translateX(-50%);z-index:800;display:flex;flex-direction:column;gap:8px;align-items:center;pointer-events:none";
        document.body.appendChild(c);
    }
    const t = document.createElement("div");
    t.textContent = msg;
    t.style.cssText = "background:" + (type === "error" ? "#dc2626" : type === "success" ? "#16a34a" : "#1f2937") + ";color:#fff;padding:11px 18px;border-radius:10px;font-size:14px;font-weight:600;box-shadow:0 6px 20px rgba(0,0,0,.25);max-width:88vw;text-align:center;opacity:0;transition:opacity .2s";
    c.appendChild(t);
    requestAnimationFrame(function() {
        t.style.opacity = "1";
    });
    setTimeout(function() {
        t.style.opacity = "0";
        setTimeout(function() {
            t.remove();
        }, 250);
    }, 2600);
}

let _promptCb = null;

function showPrompt(title, msg, placeholder, def, cb) {
    let bg = document.getElementById("promptModal");
    if (!bg) {
        bg = document.createElement("div");
        bg.className = "modal-bg";
        bg.id = "promptModal";
        bg.style.zIndex = "170";
        bg.innerHTML = '<div class="modal" style="max-width:380px"><h2 id="promptTitle" style="font-size:18px"></h2><p class="muted" id="promptMsg" style="margin:8px 0 4px;font-size:14px"></p><input id="promptInput" onkeydown="if(event.key===\'Enter\')promptOk()" style="margin-top:4px" /><div class="actions" style="justify-content:flex-end;margin-top:18px"><button class="btn secondary small" onclick="closeModal(\'promptModal\')">Batal</button><button class="btn small" onclick="promptOk()">OK</button></div></div>';
        document.body.appendChild(bg);
        bg.addEventListener("click", function(e) {
            if (e.target === bg) closeModal("promptModal");
        });
    }
    $("promptTitle").textContent = title || "";
    $("promptMsg").textContent = msg || "";
    const inp = $("promptInput");
    inp.placeholder = placeholder || "";
    inp.value = def || "";
    _promptCb = cb;
    openModal("promptModal");
    setTimeout(function() {
        inp.focus();
    }, 60);
}

function promptOk() {
    const inp = $("promptInput");
    const v = inp ? inp.value : "";
    const cb = _promptCb;
    _promptCb = null;
    closeModal("promptModal");
    if (typeof cb === "function") cb(v);
}

