/* source: assets/js/warranty-suite.js */
const legacyOpenClaimForm = window.openClaimForm;

const legacySaveClaim = window.saveClaim;

function ensureWarrantyClaimUi() {
    const modal = document.querySelector("#claimModal .modal");
    if (!modal || $("claimBusinessFields")) return;
    const actions = modal.querySelector(":scope > .actions");
    const fields = document.createElement("div");
    fields.id = "claimBusinessFields";
    fields.innerHTML = `<div id="claimContext" class="claim-context"></div><label>Penyebab klaim</label><select id="cl_cause"><option value="repeat_issue">Keluhan yang sama muncul kembali</option><option value="component_failure">Komponen pengganti bermasalah</option><option value="workmanship">Pengerjaan perlu dikoreksi</option><option value="new_issue">Keluhan baru terkait servis</option><option value="other">Lainnya</option></select><div class="frow"><div><label>Biaya internal klaim</label><input id="cl_internal_cost" inputmode="numeric" placeholder="0" oninput="fmtRupiahInput(this)"></div><div><label>Keputusan awal</label><select id="cl_decision"><option value="open">Perlu pemeriksaan</option><option value="approved">Disetujui</option></select></div></div><label>Rencana penanganan</label><textarea id="cl_resolution" rows="2" placeholder="Diagnosis ulang atau tindakan awal"></textarea>`;
    if (actions) modal.insertBefore(fields, actions);
}

function warrantyRootReport(report) {
    if (!report) return null;
    return report.original_report_id ? reports.find(item => String(item.id) === String(report.original_report_id)) || report : report;
}

function warrantyRemainingDays(report) {
    const root = warrantyRootReport(report) || report;
    const days = Number(root?.warranty_days) || 0;
    if (!days) return 0;
    const start = new Date(root.date_out || root.qc_completed_at || root.updated_at || root.date_in);
    if (Number.isNaN(start.getTime())) return days;
    const elapsed = Math.max(0, Math.floor((Date.now() - start.getTime()) / 864e5));
    return Math.max(0, days - elapsed);
}

function warrantyClaimsFor(reportId) {
    return WARRANTY_CLAIMS.filter(claim => String(claim.source_report_id) === String(reportId)).sort((a, b) => Number(a.sequence_no) - Number(b.sequence_no));
}

function warrantyEligible(report) {
    if (!report) return false;
    const final = typeof isFinalized === "function" && isFinalized(report) || /selesai|diambil/i.test(`${report.status || ""} ${report.stage || ""}`);
    return final && warrantyRemainingDays(report) > 0;
}

function warrantyCauseLabel(value) {
    return {
        repeat_issue: "Keluhan berulang",
        component_failure: "Komponen bermasalah",
        workmanship: "Koreksi pengerjaan",
        new_issue: "Keluhan baru terkait servis",
        other: "Lainnya"
    }[value] || value || "Belum ditentukan";
}

function warrantyDecisionLabel(value) {
    return {
        open: "Perlu pemeriksaan",
        approved: "Disetujui",
        rejected: "Ditolak",
        resolved: "Selesai"
    }[value] || value || "Open";
}

function openLinkedWarrantyClaim(id) {
    ensureWarrantyClaimUi();
    if (BUSINESS_SCHEMA_READY === false && legacyOpenClaimForm) {
        toast("Migrasi v3.3.0 belum aktif; menggunakan pencatatan garansi lama.", "error");
        legacyOpenClaimForm(id);
        return;
    }
    const report = reports.find(item => String(item.id) === String(id));
    if (!report) return;
    const root = warrantyRootReport(report);
    const claims = warrantyClaimsFor(root.id);
    if (!warrantyEligible(root)) {
        toast("Masa garansi sudah berakhir atau servis belum selesai.", "error");
        return;
    }
    if (claims.length >= 3) {
        toast("Batas tiga klaim untuk tiket ini sudah tercapai.", "error");
        return;
    }
    $("cl_id").value = root.id;
    $("cl_n").value = claims.length + 1;
    $("cl_keluhan").value = "";
    $("cl_sparepart").value = "";
    $("cl_ket").value = "";
    $("cl_cause").value = "repeat_issue";
    $("cl_internal_cost").value = "";
    $("cl_decision").value = "open";
    $("cl_resolution").value = "";
    $("claimFormTitle").textContent = `Buat Klaim Garansi #${claims.length + 1}`;
    $("claimContext").innerHTML = `<strong>${esc(root.ticket_no || root.device)}</strong><span>Sisa garansi ${warrantyRemainingDays(root)} hari • tiket klaim baru akan dibuat dan ditautkan ke tiket ini.</span>`;
    const saveButton = document.querySelector("#claimModal .actions .btn:not(.secondary)");
    if (saveButton) saveButton.textContent = "Buat Tiket Klaim";
    openModal("claimModal");
}

async function nextWarrantyTicketNumber() {
    let max = 0;
    try {
        const result = await db.from("reports").select("ticket_no").eq("store_id", STORE_ID).eq("job_type", "Garansi");
        (result.data || []).forEach(row => {
            const match = String(row.ticket_no || "").match(/^\s*(\d+)/);
            if (match) max = Math.max(max, Number(match[1]) || 0);
        });
    } catch (error) {}
    const tail = typeof buildTicketTail === "function" ? buildTicketTail("Garansi") : "GARANSI";
    return `${String(max + 1).padStart(3, "0")}/${tail}`;
}

async function saveLinkedWarrantyClaim() {
    if (BUSINESS_SCHEMA_READY === false && legacySaveClaim) {
        await legacySaveClaim();
        return;
    }
    if (!db) {
        toast("Supabase belum dikonfigurasi.", "error");
        return;
    }
    const sourceId = $("cl_id").value;
    const source = reports.find(item => String(item.id) === String(sourceId));
    const complaint = $("cl_keluhan").value.trim();
    if (!source || !complaint) {
        toast("Tiket asal dan keluhan wajib tersedia.", "error");
        return;
    }
    const sequence = Number($("cl_n").value) || 1;
    const remaining = warrantyRemainingDays(source);
    const now = new Date;
    const stamp = now.toISOString().slice(2, 10).replace(/-/g, "");
    const suffix = Math.random().toString(36).slice(2, 6).toUpperCase();
    const claimNo = `WG-${stamp}-${suffix}`;
    const component = $("cl_sparepart").value.trim();
    const internalCost = parseRupiah($("cl_internal_cost").value);
    const claimPayload = {
        store_id: STORE_ID,
        source_report_id: source.id,
        claim_no: claimNo,
        sequence_no: sequence,
        complaint: complaint,
        claimed_component: component,
        claim_cause: $("cl_cause").value,
        resolution_notes: $("cl_resolution").value.trim() || $("cl_ket").value.trim(),
        decision: $("cl_decision").value || "open",
        internal_cost: internalCost,
        remaining_warranty_days: remaining,
        created_by: ME.user_id || null,
        updated_at: now.toISOString()
    };
    const claimResult = await db.from("warranty_claims").insert(claimPayload).select("id,claim_no").single();
    if (claimResult.error) {
        if (businessSchemaMissing(claimResult.error)) BUSINESS_SCHEMA_READY = false;
        toast("Gagal membuat klaim: " + claimResult.error.message, "error");
        return;
    }
    const claimId = claimResult.data.id;
    const ticketNo = await nextWarrantyTicketNumber();
    const specs = {
        ...source.device_specs || {}
    };
    delete specs.claims;
    specs.warranty_source_ticket = source.ticket_no || "";
    specs.warranty_claim_no = claimNo;
    const reportPayload = {
        store_id: STORE_ID,
        ticket_no: ticketNo,
        job_type: "Garansi",
        original_report_id: source.id,
        warranty_claim_id: claimId,
        claim_sequence: sequence,
        device: source.device,
        device_type: source.device_type || "Laptop",
        device_specs: specs,
        brand: source.brand,
        customer: source.customer,
        customer_phone: source.customer_phone,
        date_in: now.toISOString().slice(0, 10),
        status: "Proses",
        stage: typeof boardStages === "function" && boardStages()[0] || "Antri",
        level: Number(source.level) || 1,
        tasks: "Diagnosis ulang klaim garansi",
        components: component ? [ component ] : [],
        assigned_to: null,
        before_notes: complaint,
        after_notes: "",
        before_media: [],
        after_media: [],
        fee: 0,
        cost: internalCost,
        cost_items: [],
        payment_status: "Lunas",
        dp_amount: 0,
        warranty_days: remaining,
        updated_at: now.toISOString()
    };
    const reportResult = await db.from("reports").insert(reportPayload).select("id,ticket_no").single();
    if (reportResult.error) {
        await db.from("warranty_claims").delete().eq("id", claimId);
        toast("Gagal membuat tiket klaim: " + reportResult.error.message, "error");
        return;
    }
    await db.from("warranty_claims").update({
        claim_report_id: reportResult.data.id,
        updated_at: now.toISOString()
    }).eq("id", claimId);
    const legacySpecs = {
        ...source.device_specs || {}
    };
    const legacyClaims = Array.isArray(legacySpecs.claims) ? legacySpecs.claims.slice() : [];
    legacyClaims.push({
        n: sequence,
        date: now.toISOString().slice(0, 10),
        keluhan: complaint,
        sparepart: component,
        keterangan: claimNo,
        report_id: reportResult.data.id
    });
    legacySpecs.claims = legacyClaims;
    await db.from("reports").update({
        device_specs: legacySpecs
    }).eq("id", source.id);
    if (typeof logWorkflowActivity === "function") {
        await logWorkflowActivity(source.id, "warranty_claim", `Klaim ${claimNo} dibuat sebagai tiket ${reportResult.data.ticket_no}.`);
        await logWorkflowActivity(reportResult.data.id, "warranty_claim", `Tiket klaim ditautkan ke ${source.ticket_no || source.id}.`);
    }
    closeModal("claimModal");
    await loadAll();
    toast(`Tiket klaim ${reportResult.data.ticket_no} berhasil dibuat.`, "success");
    openDetail(reportResult.data.id);
}

async function setWarrantyClaimDecision(claimId, decision) {
    if (!db) return;
    const update = {
        decision: decision,
        updated_at: (new Date).toISOString(),
        resolved_at: decision === "resolved" ? (new Date).toISOString() : null
    };
    const result = await db.from("warranty_claims").update(update).eq("id", claimId);
    if (result.error) {
        toast("Gagal memperbarui klaim: " + result.error.message, "error");
        return;
    }
    await loadAll();
    const claim = WARRANTY_CLAIMS.find(item => String(item.id) === String(claimId));
    toast(`Klaim ditandai ${warrantyDecisionLabel(decision)}.`, "success");
    if (claim?.claim_report_id) openDetail(claim.claim_report_id);
}

function renderWarrantyLineage(reportId) {
    const report = reports.find(item => String(item.id) === String(reportId));
    const detail = $("detailContent");
    if (!report || !detail) return;
    $("warrantyLineageCard")?.remove();
    const root = warrantyRootReport(report);
    const claims = warrantyClaimsFor(root.id);
    const currentClaim = WARRANTY_CLAIMS.find(claim => String(claim.claim_report_id) === String(report.id));
    const eligible = warrantyEligible(root) && claims.length < 3;
    const legacyButton = $("detailClaimBtn");
    if (legacyButton) legacyButton.style.display = "none";
    if (!eligible && !claims.length && !report.original_report_id) return;
    const rows = claims.length ? claims.map(claim => {
        const linked = reports.find(item => String(item.id) === String(claim.claim_report_id));
        return `<button type="button" class="warranty-history-row" onclick="${linked ? `openDetail('${linked.id}')` : "void 0"}"><span><strong>${esc(claim.claim_no)}</strong><small>${esc(linked?.ticket_no || "Tiket belum tersedia")} • ${esc(warrantyCauseLabel(claim.claim_cause))}</small></span><span class="claim-status claim-${esc(claim.decision)}">${esc(warrantyDecisionLabel(claim.decision))}</span></button>`;
    }).join("") : '<div class="business-empty">Belum ada klaim garansi.</div>';
    const relation = report.original_report_id ? `<button class="btn small secondary" type="button" onclick="openDetail('${root.id}')">Buka tiket asli ${esc(root.ticket_no || "")}</button>` : "";
    const decisionActions = currentClaim ? `<div class="warranty-decision-actions"><button class="btn small secondary" type="button" onclick="setWarrantyClaimDecision('${currentClaim.id}','approved')">Setujui</button><button class="btn small secondary" type="button" onclick="setWarrantyClaimDecision('${currentClaim.id}','rejected')">Tolak</button><button class="btn small" type="button" onclick="setWarrantyClaimDecision('${currentClaim.id}','resolved')">Selesaikan klaim</button></div>` : "";
    const card = document.createElement("section");
    card.id = "warrantyLineageCard";
    card.className = "service-tool-card warranty-lineage-card";
    card.innerHTML = `<div class="service-tool-heading"><div><span class="service-tool-kicker">Garansi terhubung</span><h3>Riwayat klaim & tiket asal</h3></div><span class="warranty-days">${warrantyRemainingDays(root)} hari tersisa</span></div><div class="warranty-source"><span>Tiket asal</span><strong>${esc(root.ticket_no || root.device)}</strong><small>${esc(root.customer || "-")} • ${esc(root.device || "-")}</small></div><div class="warranty-history">${rows}</div><div class="service-tool-actions">${relation}${eligible ? `<button class="btn small" type="button" onclick="openClaimForm('${root.id}')">+ Buat tiket klaim</button>` : ""}</div>${decisionActions}`;
    detail.appendChild(card);
}

window.openClaimForm = openLinkedWarrantyClaim;

window.saveClaim = saveLinkedWarrantyClaim;

ensureWarrantyClaimUi();

;

/* source: assets/js/inventory-core.js */
let STOCK_SUITE_VIEW = "parts";

let PO_ITEMS_STATE = [];

function ensureInventorySuiteUi() {
    const stockTab = $("tab-stock");
    if (stockTab && !$("stockSuiteNav")) {
        const heading = stockTab.querySelector(":scope > .row");
        const title = heading?.querySelector("h2");
        if (title) title.textContent = "📦 Stok, Supplier & Purchase Order";
        heading?.insertAdjacentHTML("beforeend", '<button class="btn small secondary" type="button" onclick="openSupplierForm()">+ Supplier</button><button class="btn small secondary" type="button" onclick="openPurchaseOrderForm()">+ Purchase Order</button><button class="btn small secondary" type="button" onclick="openStockMovementForm()">± Pergerakan Stok</button>');
        const toolbar = stockTab.querySelector(":scope > .toolbar");
        toolbar?.insertAdjacentHTML("beforebegin", '<div id="stockSuiteNav" class="suite-tabs"><button type="button" data-stock-view="parts" onclick="setStockSuiteView(\'parts\')">Sparepart</button><button type="button" data-stock-view="suppliers" onclick="setStockSuiteView(\'suppliers\')">Supplier</button><button type="button" data-stock-view="orders" onclick="setStockSuiteView(\'orders\')">Purchase Order</button><button type="button" data-stock-view="movements" onclick="setStockSuiteView(\'movements\')">Riwayat Stok</button></div>');
    }
    const partModal = document.querySelector("#partModal .modal");
    if (partModal && !$("partBusinessFields")) {
        const stockRow = $("pf_stock")?.closest(".frow");
        const fields = document.createElement("div");
        fields.id = "partBusinessFields";
        fields.innerHTML = `<div class="frow"><div><label>Supplier utama</label><select id="pf_supplier"></select></div><div><label>SKU / Kode</label><input id="pf_sku" placeholder="cth: LCD-14-SLIM"></div></div><label>Lokasi penyimpanan</label><input id="pf_location" placeholder="cth: Rak A2">`;
        if (stockRow) partModal.insertBefore(fields, stockRow);
    }
    if (!$("supplierModal")) document.body.insertAdjacentHTML("beforeend", `<div class="modal-bg" id="supplierModal"><div class="modal business-form-modal"><h2 id="supplierFormTitle">Tambah Supplier</h2><input type="hidden" id="sf_id"><label>Nama supplier *</label><input id="sf_name" placeholder="Nama perusahaan atau toko"><div class="frow"><div><label>Kontak person</label><input id="sf_contact" placeholder="Nama kontak"></div><div><label>WhatsApp</label><input id="sf_phone" placeholder="08xxxxxxxxxx"></div></div><label>Email</label><input id="sf_email" type="email" placeholder="supplier@example.com"><label>Alamat</label><textarea id="sf_address" rows="2"></textarea><label>Catatan</label><textarea id="sf_notes" rows="2"></textarea><div class="actions"><button class="btn secondary" type="button" onclick="closeModal('supplierModal')">Batal</button><button class="btn" type="button" onclick="saveSupplier()">Simpan Supplier</button></div></div></div>`);
    if (!$("purchaseOrderModal")) document.body.insertAdjacentHTML("beforeend", `<div class="modal-bg" id="purchaseOrderModal"><div class="modal business-form-modal po-modal"><h2 id="poFormTitle">Purchase Order</h2><input type="hidden" id="po_id"><div class="frow"><div><label>Nomor PO</label><input id="po_no" placeholder="Otomatis"></div><div><label>Supplier *</label><select id="po_supplier"></select></div></div><div class="frow"><div><label>Tanggal pesan</label><input id="po_date" type="date"></div><div><label>Estimasi tiba</label><input id="po_expected" type="date"></div></div><div class="row po-items-heading"><div><strong>Item purchase order</strong><span class="muted">Harga beli dan jumlah pesanan</span></div><button class="btn small secondary" type="button" onclick="addPurchaseOrderItem()">+ Item</button></div><div id="poItems"></div><div id="poTotal" class="po-total"></div><label>Catatan</label><textarea id="po_notes" rows="2"></textarea><div class="actions"><button class="btn secondary" type="button" onclick="closeModal('purchaseOrderModal')">Batal</button><button class="btn secondary" type="button" onclick="savePurchaseOrder('draft')">Simpan Draft</button><button class="btn" type="button" onclick="savePurchaseOrder('ordered')">Simpan & Pesan</button></div></div></div>`);
    if (!$("stockMovementModal")) document.body.insertAdjacentHTML("beforeend", `<div class="modal-bg" id="stockMovementModal"><div class="modal business-form-modal"><h2>Pergerakan Stok</h2><label>Sparepart *</label><select id="sm_part"></select><div class="frow"><div><label>Jenis</label><select id="sm_type" onchange="updateStockMovementHint()"><option value="incoming">Stok masuk</option><option value="outgoing">Stok keluar</option><option value="adjustment">Penyesuaian</option><option value="return">Retur ke supplier</option></select></div><div><label id="sm_qty_label">Jumlah</label><input id="sm_qty" type="number" min="1" placeholder="1"></div></div><div id="sm_hint" class="muted business-field-hint"></div><div class="frow"><div><label>Harga beli per unit</label><input id="sm_cost" inputmode="numeric" oninput="fmtRupiahInput(this)" placeholder="0"></div><div><label>Supplier</label><select id="sm_supplier"></select></div></div><label>Referensi</label><input id="sm_reference" placeholder="Nomor nota / dokumen"><label>Catatan</label><textarea id="sm_note" rows="2"></textarea><div class="actions"><button class="btn secondary" type="button" onclick="closeModal('stockMovementModal')">Batal</button><button class="btn" type="button" onclick="saveStockMovement()">Simpan Pergerakan</button></div></div></div>`);
    populateSupplierOptions();
}

function partReservationMap() {
    const reserved = new Map;
    reports.forEach(report => {
        if (typeof isFinalized === "function" && isFinalized(report) || /batal|gagal/i.test(`${report.status || ""} ${report.stage || ""}`)) return;
        (Array.isArray(report.cost_items) ? report.cost_items : []).forEach(item => {
            if (!item.partId || item.consumed || item.reserved === false) return;
            const key = String(item.partId);
            reserved.set(key, (reserved.get(key) || 0) + (Number(item.qty) || 1));
        });
    });
    return reserved;
}

function partReservedQty(partId) {
    return partReservationMap().get(String(partId)) || 0;
}

function partAvailableQty(part) {
    return Math.max(0, (Number(part?.stock) || 0) - partReservedQty(part?.id));
}

async function applyStockMovement({partId: partId, delta: delta, type: type, reportId: reportId = null, supplierId: supplierId = null, purchaseOrderId: purchaseOrderId = null, unitCost: unitCost = null, referenceNo: referenceNo = null, note: note = null}) {
    if (!db) throw new Error("Supabase belum dikonfigurasi.");
    const part = PARTS.find(item => String(item.id) === String(partId));
    if (!part) throw new Error("Sparepart tidak ditemukan.");
    let rpcResult = null;
    try {
        rpcResult = await db.rpc("rl_apply_stock_movement", {
            p_store_id: STORE_ID,
            p_part_id: partId,
            p_delta: Number(delta),
            p_movement_type: type,
            p_report_id: reportId,
            p_supplier_id: supplierId,
            p_purchase_order_id: purchaseOrderId,
            p_unit_cost: unitCost,
            p_reference_no: referenceNo,
            p_note: note
        });
    } catch (error) {}
    if (rpcResult && !rpcResult.error) {
        const result = rpcResult.data || {};
        part.stock = Number(result.stock_after ?? part.stock);
        return result;
    }
    if (rpcResult?.error && !businessSchemaMissing(rpcResult.error)) throw rpcResult.error;
    const before = Number(part.stock) || 0;
    const after = before + Number(delta);
    if (after < 0) throw new Error(`Stok ${part.name} tidak mencukupi.`);
    const update = {
        stock: after,
        updated_at: (new Date).toISOString()
    };
    if (Number(delta) > 0 && unitCost != null) {
        update.cost_price = Number(unitCost) || 0;
        update.last_purchase_price = Number(unitCost) || 0;
        update.last_restocked_at = (new Date).toISOString();
    }
    const partResult = await db.from("parts").update(update).eq("id", partId);
    if (partResult.error) throw partResult.error;
    part.stock = after;
    try {
        await db.from("stock_movements").insert({
            store_id: STORE_ID,
            part_id: partId,
            report_id: reportId,
            supplier_id: supplierId,
            purchase_order_id: purchaseOrderId,
            movement_type: type,
            quantity: Math.abs(Number(delta)),
            delta: Number(delta),
            stock_before: before,
            stock_after: after,
            unit_cost: unitCost,
            reference_no: referenceNo,
            note: note,
            created_by: ME.user_id || null
        });
    } catch (error) {}
    return {
        stock_before: before,
        stock_after: after
    };
}

async function finalizeReservedPartsForReport(reportId) {
    const report = reports.find(item => String(item.id) === String(reportId));
    if (!report || report.stock_finalized_at) return true;
    const items = (Array.isArray(report.cost_items) ? report.cost_items : []).map(item => ({
        ...item
    }));
    const pending = items.filter(item => item.partId && !item.consumed && item.reserved !== false);
    for (const item of pending) {
        const part = PARTS.find(candidate => String(candidate.id) === String(item.partId));
        if (!part || Number(part.stock) < (Number(item.qty) || 1)) {
            toast(`Stok ${item.label || "sparepart"} tidak mencukupi.`, "error");
            return false;
        }
    }
    try {
        for (const item of pending) {
            await applyStockMovement({
                partId: item.partId,
                delta: -(Number(item.qty) || 1),
                type: "reservation_use",
                reportId: reportId,
                unitCost: Number(item.amount) || null,
                referenceNo: report.ticket_no || null,
                note: `Pemakaian untuk tiket ${report.ticket_no || report.id}`
            });
            item.consumed = true;
            item.reserved = false;
        }
        const finalizedAt = (new Date).toISOString();
        let result = await db.from("reports").update({
            cost_items: items,
            stock_finalized_at: finalizedAt
        }).eq("id", reportId);
        if (result.error && businessSchemaMissing(result.error)) result = await db.from("reports").update({
            cost_items: items
        }).eq("id", reportId);
        if (result.error) throw result.error;
        report.cost_items = items;
        report.stock_finalized_at = finalizedAt;
        return true;
    } catch (error) {
        toast("Gagal menyelesaikan stok: " + (error.message || error), "error");
        return false;
    }
}

async function releaseReservedPartsForReport(reportId) {
    const report = reports.find(item => String(item.id) === String(reportId));
    if (!report) return;
    const items = (Array.isArray(report.cost_items) ? report.cost_items : []).map(item => item.partId && !item.consumed ? {
        ...item,
        reserved: false,
        released: true
    } : item);
    try {
        await db.from("reports").update({
            cost_items: items
        }).eq("id", reportId);
        report.cost_items = items;
    } catch (error) {}
}

function partBusinessPayload() {
    if (BUSINESS_SCHEMA_READY === false) return {};
    return {
        supplier_id: $("pf_supplier")?.value || null,
        sku: $("pf_sku")?.value.trim() || null,
        storage_location: $("pf_location")?.value.trim() || null
    };
}

function populatePartBusinessFields(part) {
    ensureInventorySuiteUi();
    populateSupplierOptions();
    if ($("pf_supplier")) $("pf_supplier").value = part?.supplier_id || "";
    if ($("pf_sku")) $("pf_sku").value = part?.sku || "";
    if ($("pf_location")) $("pf_location").value = part?.storage_location || "";
}

function setStockSuiteView(view) {
    STOCK_SUITE_VIEW = view || "parts";
    renderStock();
}

function stockOverviewHtml() {
    const reserved = PARTS.reduce((sum, part) => sum + partReservedQty(part.id), 0);
    const low = PARTS.filter(part => partAvailableQty(part) <= Number(part.min_stock || 0)).length;
    const value = PARTS.reduce((sum, part) => sum + (Number(part.stock) || 0) * (Number(part.cost_price) || 0), 0);
    return `<div class="business-stat-grid"><div><span>Jenis sparepart</span><strong>${PARTS.length}</strong></div><div><span>Unit dicadangkan</span><strong>${reserved}</strong></div><div><span>Perlu restock</span><strong>${low}</strong></div><div><span>Nilai stok</span><strong>${rpShort(value)}</strong></div></div>`;
}

function renderAdvancedStock() {
    ensureInventorySuiteUi();
    const box = $("stockBox");
    if (!box) return;
    document.querySelectorAll("#stockSuiteNav button").forEach(button => button.classList.toggle("active", button.dataset.stockView === STOCK_SUITE_VIEW));
    const toolbar = $("stockDevFilter")?.closest(".toolbar");
    if (toolbar) toolbar.style.display = STOCK_SUITE_VIEW === "parts" ? "" : "none";
    if (BUSINESS_SCHEMA_READY === false) {
        box.innerHTML = businessMigrationNotice() + stockOverviewHtml() + renderAdvancedPartsTable();
        return;
    }
    let content = "";
    if (STOCK_SUITE_VIEW === "parts") content = renderAdvancedPartsTable();
    if (STOCK_SUITE_VIEW === "suppliers") content = renderSupplierTable();
    if (STOCK_SUITE_VIEW === "orders") content = renderPurchaseOrderTable();
    if (STOCK_SUITE_VIEW === "movements") content = renderStockMovementTable();
    box.innerHTML = stockOverviewHtml() + content;
}

function renderAdvancedPartsTable() {
    ensureDevFilter("stockDevFilter");
    const list = stockFilteredParts();
    const rows = list.length ? list.map(part => {
        const reserved = partReservedQty(part.id), available = partAvailableQty(part);
        const low = available <= Number(part.min_stock || 0);
        return `<tr><td><strong>${esc(part.name)}</strong><small>${esc(part.sku || part.category || "Tanpa SKU")}</small></td><td>${esc(part.device_type || "Umum")}</td><td>${esc(supplierName(part.supplier_id))}</td><td>${Number(part.stock) || 0}</td><td>${reserved}</td><td class="${low ? "stock-low" : ""}">${available}${low ? " • restock" : ""}</td><td>${rp(part.cost_price || 0)}</td><td>${esc(part.storage_location || "-")}</td><td><div class="table-actions"><button class="btn small secondary" onclick="openStockMovementForm('${part.id}')">± Stok</button><button class="btn small secondary" onclick="openPartForm('${part.id}')">Edit</button></div></td></tr>`;
    }).join("") : '<tr><td colspan="9"><div class="business-empty">Belum ada sparepart.</div></td></tr>';
    return `<div class="business-table-wrap"><table class="ftbl business-table"><thead><tr><th>Sparepart</th><th>Perangkat</th><th>Supplier</th><th>Fisik</th><th>Reservasi</th><th>Tersedia</th><th>Harga beli</th><th>Lokasi</th><th>Aksi</th></tr></thead><tbody>${rows}</tbody></table></div>`;
}

function renderSupplierTable() {
    const rows = SUPPLIERS.length ? SUPPLIERS.map(supplier => `<tr><td><strong>${esc(supplier.name)}</strong><small>${supplier.active === false ? "Nonaktif" : "Aktif"}</small></td><td>${esc(supplier.contact_person || "-")}</td><td>${esc(supplier.phone || supplier.email || "-")}</td><td>${PARTS.filter(part => String(part.supplier_id) === String(supplier.id)).length}</td><td>${PURCHASE_ORDERS.filter(order => String(order.supplier_id) === String(supplier.id)).length}</td><td><div class="table-actions"><button class="btn small secondary" onclick="openSupplierForm('${supplier.id}')">Edit</button><button class="btn small secondary" onclick="openPurchaseOrderForm(null,'${supplier.id}')">Buat PO</button></div></td></tr>`).join("") : '<tr><td colspan="6"><div class="business-empty">Belum ada supplier.</div></td></tr>';
    return `<div class="business-table-wrap"><table class="ftbl business-table"><thead><tr><th>Supplier</th><th>Kontak</th><th>Telepon / email</th><th>Sparepart</th><th>PO</th><th>Aksi</th></tr></thead><tbody>${rows}</tbody></table></div>`;
}

function poStatusLabel(status) {
    return {
        draft: "Draft",
        ordered: "Dipesan",
        partial: "Sebagian",
        received: "Diterima",
        cancelled: "Dibatalkan"
    }[status] || status;
}

function renderPurchaseOrderTable() {
    const rows = PURCHASE_ORDERS.length ? PURCHASE_ORDERS.map(order => {
        const receive = [ "ordered", "partial" ].includes(order.status) ? `<button class="btn small" onclick="receivePurchaseOrder('${order.id}')">Terima barang</button>` : "";
        return `<tr><td><strong>${esc(order.order_no)}</strong><small>${fmtDate(order.order_date)}</small></td><td>${esc(supplierName(order.supplier_id))}</td><td>${Array.isArray(order.items) ? order.items.length : 0} item</td><td>${rp(order.total_amount || 0)}</td><td><span class="po-status po-${esc(order.status)}">${esc(poStatusLabel(order.status))}</span></td><td>${order.expected_at ? fmtDate(order.expected_at) : "-"}</td><td><div class="table-actions"><button class="btn small secondary" onclick="openPurchaseOrderForm('${order.id}')">Detail</button>${receive}</div></td></tr>`;
    }).join("") : '<tr><td colspan="7"><div class="business-empty">Belum ada purchase order.</div></td></tr>';
    return `<div class="business-table-wrap"><table class="ftbl business-table"><thead><tr><th>Nomor PO</th><th>Supplier</th><th>Item</th><th>Total</th><th>Status</th><th>Estimasi</th><th>Aksi</th></tr></thead><tbody>${rows}</tbody></table></div>`;
}

function movementTypeLabel(type) {
    return {
        incoming: "Stok masuk",
        outgoing: "Stok keluar",
        reservation_use: "Dipakai tiket",
        adjustment: "Penyesuaian",
        po_receipt: "Penerimaan PO",
        return: "Retur"
    }[type] || type;
}

function renderStockMovementTable() {
    const rows = STOCK_MOVEMENTS.length ? STOCK_MOVEMENTS.slice(0, 120).map(movement => {
        const part = PARTS.find(item => String(item.id) === String(movement.part_id));
        const report = reports.find(item => String(item.id) === String(movement.report_id));
        return `<tr><td>${new Date(movement.created_at).toLocaleString("id-ID")}</td><td><strong>${esc(part?.name || "Sparepart")}</strong><small>${esc(movement.reference_no || report?.ticket_no || "-")}</small></td><td>${esc(movementTypeLabel(movement.movement_type))}</td><td class="${Number(movement.delta) > 0 ? "stock-in" : "stock-out"}">${Number(movement.delta) > 0 ? "+" : ""}${movement.delta}</td><td>${movement.stock_before} → ${movement.stock_after}</td><td>${esc(movement.note || "-")}</td></tr>`;
    }).join("") : '<tr><td colspan="6"><div class="business-empty">Belum ada pergerakan stok.</div></td></tr>';
    return `<div class="business-table-wrap"><table class="ftbl business-table"><thead><tr><th>Waktu</th><th>Sparepart</th><th>Jenis</th><th>Delta</th><th>Stok</th><th>Catatan</th></tr></thead><tbody>${rows}</tbody></table></div>`;
}

ensureInventorySuiteUi();

;

/* source: assets/js/inventory-suite.js */
function openSupplierForm(id) {
    ensureInventorySuiteUi();
    const supplier = SUPPLIERS.find(item => String(item.id) === String(id));
    $("sf_id").value = supplier?.id || "";
    $("sf_name").value = supplier?.name || "";
    $("sf_contact").value = supplier?.contact_person || "";
    $("sf_phone").value = supplier?.phone || "";
    $("sf_email").value = supplier?.email || "";
    $("sf_address").value = supplier?.address || "";
    $("sf_notes").value = supplier?.notes || "";
    $("supplierFormTitle").textContent = supplier ? "Edit Supplier" : "Tambah Supplier";
    openModal("supplierModal");
}

async function saveSupplier() {
    const name = $("sf_name").value.trim();
    if (!name) {
        toast("Nama supplier wajib diisi.", "error");
        return;
    }
    const payload = {
        store_id: STORE_ID,
        name: name,
        contact_person: $("sf_contact").value.trim() || null,
        phone: $("sf_phone").value.trim() || null,
        email: $("sf_email").value.trim() || null,
        address: $("sf_address").value.trim() || null,
        notes: $("sf_notes").value.trim() || null,
        active: true,
        created_by: ME.user_id || null,
        updated_at: (new Date).toISOString()
    };
    const id = $("sf_id").value;
    const result = id ? await db.from("suppliers").update(payload).eq("id", id) : await db.from("suppliers").insert(payload);
    if (result.error) {
        toast("Gagal menyimpan supplier: " + result.error.message, "error");
        return;
    }
    closeModal("supplierModal");
    await loadBusinessSuiteData();
    renderStock();
    toast("Supplier tersimpan.", "success");
}

function makePurchaseOrderNo() {
    const date = (new Date).toISOString().slice(2, 10).replace(/-/g, "");
    return `PO-${date}-${String(PURCHASE_ORDERS.length + 1).padStart(3, "0")}`;
}

function openPurchaseOrderForm(id, supplierId) {
    ensureInventorySuiteUi();
    populateSupplierOptions();
    const order = PURCHASE_ORDERS.find(item => String(item.id) === String(id));
    $("po_id").value = order?.id || "";
    $("po_no").value = order?.order_no || makePurchaseOrderNo();
    $("po_supplier").value = order?.supplier_id || supplierId || "";
    $("po_date").value = order?.order_date || (new Date).toISOString().slice(0, 10);
    $("po_expected").value = order?.expected_at || "";
    $("po_notes").value = order?.notes || "";
    PO_ITEMS_STATE = Array.isArray(order?.items) ? order.items.map(item => ({
        ...item
    })) : [ {
        part_id: "",
        name: "",
        qty: 1,
        unit_cost: 0
    } ];
    $("poFormTitle").textContent = order ? `Purchase Order ${order.order_no}` : "Buat Purchase Order";
    renderPurchaseOrderItems();
    openModal("purchaseOrderModal");
}

function addPurchaseOrderItem() {
    PO_ITEMS_STATE.push({
        part_id: "",
        name: "",
        qty: 1,
        unit_cost: 0
    });
    renderPurchaseOrderItems();
}

function removePurchaseOrderItem(index) {
    PO_ITEMS_STATE.splice(index, 1);
    if (!PO_ITEMS_STATE.length) addPurchaseOrderItem(); else renderPurchaseOrderItems();
}

function updatePurchaseOrderItem(index, key, value) {
    const item = PO_ITEMS_STATE[index];
    if (!item) return;
    item[key] = [ "qty", "unit_cost" ].includes(key) ? Number(value) || 0 : value;
    if (key === "part_id") {
        const part = PARTS.find(candidate => String(candidate.id) === String(value));
        item.name = part?.name || "";
        if (!item.unit_cost) item.unit_cost = Number(part?.cost_price) || 0;
        renderPurchaseOrderItems();
    } else {
        renderPurchaseOrderTotal();
    }
}

function renderPurchaseOrderItems() {
    const root = $("poItems");
    if (!root) return;
    const options = PARTS.map(part => `<option value="${part.id}">${esc(part.name)}</option>`).join("");
    root.innerHTML = PO_ITEMS_STATE.map((item, index) => {
        const selectedOptions = '<option value="">Pilih sparepart</option>' + options.replace(`value="${item.part_id}"`, `value="${item.part_id}" selected`);
        return `<div class="po-item-row"><select onchange="updatePurchaseOrderItem(${index},'part_id',this.value)">${selectedOptions}</select><input type="number" min="1" value="${Number(item.qty) || 1}" aria-label="Jumlah" onchange="updatePurchaseOrderItem(${index},'qty',this.value)"><input type="number" min="0" value="${Number(item.unit_cost) || 0}" aria-label="Harga beli" onchange="updatePurchaseOrderItem(${index},'unit_cost',this.value)"><strong>${rp((Number(item.qty) || 0) * (Number(item.unit_cost) || 0))}</strong><button class="btn small secondary" type="button" onclick="removePurchaseOrderItem(${index})">×</button></div>`;
    }).join("");
    renderPurchaseOrderTotal();
}

function renderPurchaseOrderTotal() {
    const total = PO_ITEMS_STATE.reduce((sum, item) => sum + (Number(item.qty) || 0) * (Number(item.unit_cost) || 0), 0);
    if ($("poTotal")) $("poTotal").innerHTML = `<span>Total PO</span><strong>${rp(total)}</strong>`;
}

async function savePurchaseOrder(status) {
    const supplierId = $("po_supplier").value;
    const items = PO_ITEMS_STATE.filter(item => item.part_id && (Number(item.qty) || 0) > 0);
    if (!supplierId || !items.length) {
        toast("Supplier dan minimal satu item wajib diisi.", "error");
        return;
    }
    const total = items.reduce((sum, item) => sum + Number(item.qty) * Number(item.unit_cost || 0), 0);
    const payload = {
        store_id: STORE_ID,
        order_no: $("po_no").value.trim() || makePurchaseOrderNo(),
        supplier_id: supplierId,
        status: status || "draft",
        order_date: $("po_date").value,
        expected_at: $("po_expected").value || null,
        items: items,
        total_amount: total,
        notes: $("po_notes").value.trim() || null,
        created_by: ME.user_id || null,
        updated_at: (new Date).toISOString()
    };
    const id = $("po_id").value;
    const result = id ? await db.from("purchase_orders").update(payload).eq("id", id) : await db.from("purchase_orders").insert(payload);
    if (result.error) {
        toast("Gagal menyimpan PO: " + result.error.message, "error");
        return;
    }
    closeModal("purchaseOrderModal");
    await loadBusinessSuiteData();
    setStockSuiteView("orders");
    toast(status === "ordered" ? "Purchase order dibuat." : "Draft PO tersimpan.", "success");
}

function receivePurchaseOrder(id) {
    const order = PURCHASE_ORDERS.find(item => String(item.id) === String(id));
    if (!order) return;
    showMini("Terima purchase order", `Tambahkan seluruh item ${order.order_no} ke stok?`, [ {
        label: "Batal",
        cls: "secondary",
        fn: null
    }, {
        label: "Terima semua",
        fn: async () => {
            try {
                for (const item of order.items || []) {
                    await applyStockMovement({
                        partId: item.part_id,
                        delta: Number(item.qty) || 0,
                        type: "po_receipt",
                        supplierId: order.supplier_id,
                        purchaseOrderId: order.id,
                        unitCost: Number(item.unit_cost) || 0,
                        referenceNo: order.order_no,
                        note: "Penerimaan purchase order"
                    });
                }
                await db.from("purchase_orders").update({
                    status: "received",
                    received_at: (new Date).toISOString(),
                    updated_at: (new Date).toISOString()
                }).eq("id", id);
                await loadParts();
                await loadBusinessSuiteData();
                renderStock();
                toast("Purchase order diterima dan stok diperbarui.", "success");
            } catch (error) {
                toast("Gagal menerima PO: " + (error.message || error), "error");
            }
        }
    } ]);
}

function openStockMovementForm(partId, type) {
    ensureInventorySuiteUi();
    $("sm_part").innerHTML = '<option value="">Pilih sparepart</option>' + PARTS.map(part => `<option value="${part.id}">${esc(part.name)} • stok ${Number(part.stock) || 0}</option>`).join("");
    $("sm_part").value = partId || "";
    $("sm_type").value = type || "incoming";
    $("sm_qty").value = "";
    $("sm_cost").value = "";
    $("sm_supplier").value = "";
    $("sm_reference").value = "";
    $("sm_note").value = "";
    updateStockMovementHint();
    openModal("stockMovementModal");
}

function updateStockMovementHint() {
    const type = $("sm_type")?.value;
    if ($("sm_qty_label")) $("sm_qty_label").textContent = type === "adjustment" ? "Stok fisik baru" : "Jumlah";
    if ($("sm_hint")) $("sm_hint").textContent = type === "adjustment" ? "Masukkan jumlah stok fisik hasil perhitungan, bukan selisihnya." : type === "return" ? "Jumlah akan dikurangi dari stok dan dicatat sebagai retur." : "Perubahan akan masuk ke ledger stok.";
}

let stockMovementSaving = false;

async function saveStockMovement() {
    if (stockMovementSaving) return;
    const part = PARTS.find(item => String(item.id) === String($("sm_part").value));
    const type = $("sm_type").value;
    const input = Number($("sm_qty").value);
    if (!part || input < 0 || !input && type !== "adjustment") {
        toast("Sparepart dan jumlah wajib valid.", "error");
        return;
    }
    let delta = input;
    if ([ "outgoing", "return" ].includes(type)) delta = -input;
    if (type === "adjustment") delta = input - (Number(part.stock) || 0);
    if (!delta) {
        toast("Tidak ada perubahan stok.", "error");
        return;
    }
    if (typeof confirmStockReduction === "function" && !await confirmStockReduction(part, delta, type)) return;
    stockMovementSaving = true;
    try {
        await applyStockMovement({
            partId: part.id,
            delta: delta,
            type: type,
            supplierId: $("sm_supplier").value || null,
            unitCost: parseRupiah($("sm_cost").value) || null,
            referenceNo: $("sm_reference").value.trim() || null,
            note: $("sm_note").value.trim() || null
        });
        closeModal("stockMovementModal");
        await loadParts();
        await loadBusinessSuiteData();
        renderStock();
        toast("Pergerakan stok tersimpan.", "success");
    } catch (error) {
        toast("Gagal mengubah stok: " + (error.message || error), "error");
    } finally {
        stockMovementSaving = false;
    }
}

ensureInventorySuiteUi();

;

/* source: assets/js/analytics.js */
let ANALYTICS_RANGE = "90d";

function analyticsRangeStart() {
    const now = new Date;
    if (ANALYTICS_RANGE === "all") return null;
    if (ANALYTICS_RANGE === "year") return new Date(now.getFullYear(), 0, 1);
    const days = Number(ANALYTICS_RANGE.replace("d", "")) || 90;
    return new Date(now.getTime() - days * 864e5);
}

function analyticsReports() {
    const start = analyticsRangeStart();
    return reports.filter(report => {
        if (!start) return true;
        const date = new Date(report.date_in || report.created_at || 0);
        return !Number.isNaN(date.getTime()) && date >= start;
    });
}

function analyticsFinishDate(report) {
    return new Date(report.date_out || report.qc_completed_at || report.updated_at || report.date_in);
}

function analyticsMetricCard(label, value, helper, tone) {
    return `<article class="analytics-metric ${tone || ""}"><span>${esc(label)}</span><strong>${esc(value)}</strong><small>${esc(helper || "")}</small></article>`;
}

function analyticsBarList(items, emptyText) {
    if (!items.length) return `<div class="business-empty">${esc(emptyText)}</div>`;
    const max = Math.max(...items.map(item => Number(item.value) || 0), 1);
    return `<div class="analytics-bars">${items.map(item => `<div class="analytics-bar-row"><div><strong>${esc(item.label)}</strong><span>${esc(item.meta || String(item.value))}</span></div><div class="analytics-bar-track"><span style="width:${Math.max(4, (Number(item.value) || 0) / max * 100)}%;background:${item.color || "var(--accent)"}"></span></div></div>`).join("")}</div>`;
}

function analyticsGroupCount(list, getter, limit = 6) {
    const map = new Map;
    list.forEach(item => {
        const key = getter(item) || "Lainnya";
        map.set(key, (map.get(key) || 0) + 1);
    });
    return [ ...map.entries() ].map(([label, value]) => ({
        label: label,
        value: value
    })).sort((a, b) => b.value - a.value).slice(0, limit);
}

function analyticsMonthlyTrend(list) {
    const map = new Map;
    list.forEach(report => {
        const key = String(report.date_in || report.created_at || "").slice(0, 7);
        if (!key) return;
        const current = map.get(key) || {
            tickets: 0,
            revenue: 0
        };
        current.tickets += 1;
        current.revenue += Number(report.fee) || 0;
        map.set(key, current);
    });
    return [ ...map.entries() ].sort(([a], [b]) => a.localeCompare(b)).slice(-8).map(([label, value]) => ({
        label: new Date(`${label}-01T00:00:00`).toLocaleDateString("id-ID", {
            month: "short",
            year: "2-digit"
        }),
        value: value.revenue,
        meta: `${value.tickets} tiket • ${rpShort(value.revenue)}`
    }));
}

function renderAnalytics() {
    const root = $("analyticsBox");
    if (!root) return;
    const list = analyticsReports();
    const completed = list.filter(report => typeof isFinalized === "function" ? isFinalized(report) : /selesai|diambil/i.test(report.status || ""));
    const turnaround = completed.map(report => {
        const start = new Date(report.date_in || report.created_at);
        const end = analyticsFinishDate(report);
        return Math.max(0, (end - start) / 864e5);
    }).filter(Number.isFinite);
    const avgDays = turnaround.length ? turnaround.reduce((sum, value) => sum + value, 0) / turnaround.length : 0;
    const slaRows = completed.filter(report => report.sla_due_at);
    const slaOnTime = slaRows.filter(report => analyticsFinishDate(report) <= new Date(report.sla_due_at)).length;
    const approvalRows = list.filter(report => [ "approved", "rejected" ].includes(report.approval_status));
    const approved = approvalRows.filter(report => report.approval_status === "approved").length;
    const sourceIdsWithClaims = new Set(WARRANTY_CLAIMS.map(claim => String(claim.source_report_id)));
    const firstTimeFixed = completed.filter(report => !sourceIdsWithClaims.has(String(report.id))).length;
    const revenue = list.reduce((sum, report) => sum + (Number(report.fee) || 0), 0);
    const cost = list.reduce((sum, report) => sum + (Number(report.cost) || 0), 0);
    const margin = revenue - cost;
    const marginRate = revenue ? margin / revenue * 100 : 0;
    const claimsInRange = WARRANTY_CLAIMS.filter(claim => list.some(report => String(report.id) === String(claim.source_report_id)));
    const repeatRate = completed.length ? claimsInRange.length / completed.length * 100 : 0;
    const devices = analyticsGroupCount(list, report => report.device_type || "Perangkat");
    const brands = analyticsGroupCount(list, report => report.brand || "Tanpa merek");
    const stages = analyticsGroupCount(list, report => report.stage || report.status);
    const partMap = new Map;
    list.forEach(report => (Array.isArray(report.cost_items) ? report.cost_items : []).forEach(item => {
        if (!item.label) return;
        partMap.set(item.label, (partMap.get(item.label) || 0) + (Number(item.qty) || 1));
    }));
    const topParts = [ ...partMap.entries() ].map(([label, value]) => ({
        label: label,
        value: value
    })).sort((a, b) => b.value - a.value).slice(0, 6);
    const productivity = analyticsGroupCount(completed, report => TEAM.find(member => String(member.user_id) === String(report.assigned_to))?.name || "Belum ditugaskan");
    const monthly = analyticsMonthlyTrend(list);
    root.innerHTML = `<div class="analytics-toolbar"><div><span class="dashboard-kicker">Analitik bisnis</span><h2>Kesehatan operasional servis</h2><p>Ringkasan SLA, kecepatan servis, kualitas, margin, dan beban kerja.</p></div><div><select id="analyticsRange" onchange="setAnalyticsRange(this.value)"><option value="30d">30 hari</option><option value="90d">90 hari</option><option value="year">Tahun berjalan</option><option value="all">Semua data</option></select><button class="btn small secondary" type="button" onclick="exportAnalyticsCsv()">Ekspor CSV</button></div></div><div class="analytics-metric-grid">${analyticsMetricCard("Rata-rata selesai", `${avgDays.toFixed(1)} hari`, `${completed.length} tiket selesai`, "tone-blue")}${analyticsMetricCard("Tepat SLA", `${slaRows.length ? Math.round(slaOnTime / slaRows.length * 100) : 0}%`, `${slaOnTime}/${slaRows.length} tiket`, "tone-green")}${analyticsMetricCard("First-time fix", `${completed.length ? Math.round(firstTimeFixed / completed.length * 100) : 0}%`, "Tidak kembali sebagai klaim", "tone-purple")}${analyticsMetricCard("Servis berulang", `${repeatRate.toFixed(1)}%`, `${claimsInRange.length} klaim tercatat`, repeatRate > 10 ? "tone-orange" : "tone-green")}${analyticsMetricCard("Persetujuan estimasi", `${approvalRows.length ? Math.round(approved / approvalRows.length * 100) : 0}%`, `${approved}/${approvalRows.length} disetujui`, "tone-blue")}${analyticsMetricCard("Margin kotor", `${marginRate.toFixed(1)}%`, `${rpShort(margin)} dari ${rpShort(revenue)}`, margin >= 0 ? "tone-green" : "tone-red")}</div><div class="analytics-grid"><section class="analytics-panel analytics-panel-wide"><div class="analytics-panel-head"><h3>Tren pendapatan</h3><span>Delapan bulan terakhir</span></div>${analyticsBarList(monthly, "Belum ada data pendapatan.")}</section><section class="analytics-panel"><div class="analytics-panel-head"><h3>Jenis perangkat</h3><span>${list.length} tiket</span></div>${analyticsBarList(devices, "Belum ada data perangkat.")}</section><section class="analytics-panel"><div class="analytics-panel-head"><h3>Merek paling sering masuk</h3><span>Top ${brands.length}</span></div>${analyticsBarList(brands, "Belum ada data merek.")}</section><section class="analytics-panel"><div class="analytics-panel-head"><h3>Distribusi tahap</h3><span>Posisi tiket saat ini</span></div>${analyticsBarList(stages, "Belum ada data tahap.")}</section><section class="analytics-panel"><div class="analytics-panel-head"><h3>Sparepart terpakai</h3><span>Berdasarkan tiket</span></div>${analyticsBarList(topParts, "Belum ada pemakaian sparepart.")}</section><section class="analytics-panel analytics-panel-wide"><div class="analytics-panel-head"><h3>Produktivitas pengguna</h3><span>Tiket selesai</span></div>${analyticsBarList(productivity, "Belum ada tiket selesai.")}</section></div>`;
    if ($("analyticsRange")) $("analyticsRange").value = ANALYTICS_RANGE;
}

function setAnalyticsRange(value) {
    ANALYTICS_RANGE = value || "90d";
    renderAnalytics();
}

function exportAnalyticsCsv() {
    const list = analyticsReports();
    const rows = [ [ "No Tiket", "Tanggal Masuk", "Pelanggan", "Perangkat", "Merek", "Status", "Tahap", "Level", "Pendapatan", "Modal", "Margin", "SLA", "QC", "Tiket Asal" ], ...list.map(report => [ report.ticket_no || "", report.date_in || "", report.customer || "", report.device || "", report.brand || "", report.status || "", report.stage || "", report.level || "", Number(report.fee) || 0, Number(report.cost) || 0, (Number(report.fee) || 0) - (Number(report.cost) || 0), report.sla_due_at || "", report.qc_status || "", report.original_report_id || "" ]) ];
    const csv = rows.map(row => row.map(value => `"${String(value ?? "").replace(/"/g, '""')}"`).join(",")).join("\n");
    const blob = new Blob([ "\ufeff" + csv ], {
        type: "text/csv;charset=utf-8"
    });
    const url = URL.createObjectURL(blob);
    const anchor = document.createElement("a");
    anchor.href = url;
    anchor.download = `repairlog-analytics-${(new Date).toISOString().slice(0, 10)}.csv`;
    anchor.click();
    setTimeout(() => URL.revokeObjectURL(url), 500);
}

;

/* source: assets/js/productivity.js */
const REPORT_WIZARD_STEPS = [ {
    label: "Jenis servis & tiket",
    short: "Tiket"
}, {
    label: "Pelanggan & perangkat",
    short: "Perangkat"
}, {
    label: "Keluhan & target",
    short: "Diagnosis"
}, {
    label: "Pengerjaan",
    short: "Pengerjaan"
}, {
    label: "Biaya & sparepart",
    short: "Biaya"
}, {
    label: "Dokumentasi",
    short: "Dokumentasi"
}, {
    label: "Review & simpan",
    short: "Review"
} ];

let reportWizardStep = 0;

let reportWizardReportId = "new";

let reportWizardInitialized = false;

let reportWizardRestoring = false;

let reportDraftTimer = null;

let commandSelection = 0;

let commandResults = [];

function productivityIcon(name) {
    const paths = {
        search: '<circle cx="11" cy="11" r="7"></circle><path d="m20 20-3.8-3.8"></path>',
        home: '<path d="m3 11 9-8 9 8"></path><path d="M5 10v10h14V10"></path>',
        board: '<rect x="3" y="4" width="5" height="16" rx="1"></rect><rect x="10" y="4" width="5" height="11" rx="1"></rect><rect x="17" y="4" width="4" height="7" rx="1"></rect>',
        plus: '<path d="M12 5v14M5 12h14"></path>',
        users: '<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"></path><circle cx="9" cy="7" r="4"></circle><path d="M22 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"></path>',
        more: '<circle cx="5" cy="12" r="1"></circle><circle cx="12" cy="12" r="1"></circle><circle cx="19" cy="12" r="1"></circle>',
        ticket: '<path d="M3 7a2 2 0 0 0 0 4v6h18v-6a2 2 0 0 0 0-4V5H3z"></path><path d="M8 5v12"></path>',
        close: '<path d="M6 6l12 12M18 6 6 18"></path>',
        arrow: '<path d="m9 18 6-6-6-6"></path>'
    };
    return `<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${paths[name] || paths.search}</svg>`;
}

function normalizeSearchText(value) {
    return String(value || "").normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase().trim();
}

function globalSearchHaystack(report) {
    return normalizeSearchText([ report.ticket_no, report.customer, report.customer_phone, report.brand, report.device, report.device_type, report.status, report.stage, report.tasks, report.before_notes, report.after_notes, report.delay_reason, report.approval_note, Array.isArray(report.components) ? report.components.join(" ") : "" ].join(" "));
}

function globalSearchScore(report, query) {
    const q = normalizeSearchText(query);
    if (!q) return 1;
    const ticket = normalizeSearchText(report.ticket_no);
    const customer = normalizeSearchText(report.customer);
    const phone = normalizeSearchText(report.customer_phone).replace(/\D/g, "");
    const compact = q.replace(/\D/g, "");
    const haystack = globalSearchHaystack(report);
    let score = 0;
    if (ticket === q) score += 180; else if (ticket.startsWith(q)) score += 120; else if (ticket.includes(q)) score += 90;
    if (customer === q) score += 130; else if (customer.startsWith(q)) score += 95; else if (customer.includes(q)) score += 65;
    if (compact && phone.includes(compact)) score += 80;
    q.split(/\s+/).forEach(token => {
        if (token && haystack.includes(token)) score += 18;
    });
    return score;
}

function recentSearchReports() {
    let ids = [];
    try {
        ids = JSON.parse(localStorage.getItem("rl_recent_reports") || "[]");
    } catch (error) {}
    const recent = ids.map(id => reports.find(report => String(report.id) === String(id))).filter(Boolean);
    const remaining = reports.filter(report => !ids.includes(String(report.id))).slice(0, Math.max(0, 7 - recent.length));
    return recent.concat(remaining).slice(0, 7);
}

function rememberSearchReport(id) {
    try {
        const current = JSON.parse(localStorage.getItem("rl_recent_reports") || "[]");
        const next = [ String(id), ...current.filter(item => String(item) !== String(id)) ].slice(0, 8);
        localStorage.setItem("rl_recent_reports", JSON.stringify(next));
    } catch (error) {}
}

function searchReportsGlobally(query) {
    const q = normalizeSearchText(query);
    if (!q) return recentSearchReports();
    return reports.map(report => ({
        report: report,
        score: globalSearchScore(report, q)
    })).filter(item => item.score > 0).sort((a, b) => b.score - a.score || new Date(b.report.updated_at || b.report.created_at || 0) - new Date(a.report.updated_at || a.report.created_at || 0)).slice(0, 10).map(item => item.report);
}

function quickActionMarkup() {
    return `<div class="command-quick-grid"><button type="button" onclick="runQuickAction('add')"><span>${productivityIcon("plus")}</span><strong>Tambah tiket</strong><small>Buat laporan servis</small></button><button type="button" onclick="runQuickAction('board')"><span>${productivityIcon("board")}</span><strong>Buka papan</strong><small>Lihat alur pekerjaan</small></button><button type="button" onclick="runQuickAction('actions')"><span>${productivityIcon("home")}</span><strong>Pusat Tindakan</strong><small>Fokus pekerjaan hari ini</small></button><button type="button" onclick="runQuickAction('ticket')"><span>${productivityIcon("ticket")}</span><strong>Buka tiket / QR</strong><small>Tempel nomor atau link</small></button><button type="button" onclick="runQuickAction('customers')"><span>${productivityIcon("users")}</span><strong>Pelanggan</strong><small>Buka riwayat servis</small></button><button type="button" onclick="runQuickAction('finance')"><span>${productivityIcon("more")}</span><strong>Keuangan</strong><small>Catat dan cek pembayaran</small></button></div>`;
}

function renderGlobalSearch() {
    const input = $("globalSearchInput");
    const root = $("globalSearchResults");
    if (!input || !root) return;
    const query = input.value.trim();
    commandResults = searchReportsGlobally(query);
    if (commandSelection >= commandResults.length) commandSelection = Math.max(0, commandResults.length - 1);
    const quick = query ? "" : `<div class="command-section-label">Quick action</div>${quickActionMarkup()}<div class="command-section-label">Tiket terbaru</div>`;
    const results = commandResults.length ? commandResults.map((report, index) => {
        const stage = report.stage || report.status || "Proses";
        const secondary = [ report.customer || "Tanpa nama", report.device || "Perangkat", stage ].filter(Boolean).join(" • ");
        return `<button type="button" class="command-result ${index === commandSelection ? "is-selected" : ""}" data-command-index="${index}" onclick="openGlobalSearchReport('${report.id}')"><span class="command-result-icon">${productivityIcon("ticket")}</span><span><strong>${esc(report.ticket_no || report.device || "Tiket servis")}</strong><small>${esc(secondary)}</small></span><span class="command-result-status">L${Number(report.level) || 1}</span></button>`;
    }).join("") : `<div class="command-empty"><strong>Tidak ada tiket yang cocok</strong><span>Coba nomor tiket, nama, WhatsApp, merek, status, atau catatan servis.</span></div>`;
    root.innerHTML = `${quick}${results}`;
}

function openGlobalSearch(initialValue) {
    const palette = $("globalSearchPalette");
    const input = $("globalSearchInput");
    if (!palette || !input) return;
    closeNavMenu();
    palette.classList.add("open");
    palette.setAttribute("aria-hidden", "false");
    input.value = initialValue || "";
    commandSelection = 0;
    renderGlobalSearch();
    setTimeout(() => input.focus(), 40);
}

function closeGlobalSearch() {
    const palette = $("globalSearchPalette");
    if (!palette) return;
    palette.classList.remove("open");
    palette.setAttribute("aria-hidden", "true");
}

function openGlobalSearchReport(id) {
    const report = reports.find(item => String(item.id) === String(id));
    if (!report) return;
    rememberSearchReport(id);
    closeGlobalSearch();
    openDetail(id);
}

function handleGlobalSearchKey(event) {
    if (event.key === "ArrowDown") {
        event.preventDefault();
        commandSelection = Math.min(commandResults.length - 1, commandSelection + 1);
        renderGlobalSearch();
    } else if (event.key === "ArrowUp") {
        event.preventDefault();
        commandSelection = Math.max(0, commandSelection - 1);
        renderGlobalSearch();
    } else if (event.key === "Enter" && commandResults.length) {
        event.preventDefault();
        openGlobalSearchReport(commandResults[commandSelection].id);
    } else if (event.key === "Escape") {
        closeGlobalSearch();
    }
}

function openTicketFromCode(value) {
    const raw = String(value || "").trim();
    if (!raw) return;
    const routeMatch = raw.match(/#\/(?:c|t|g)\/([^/?#]+)/i);
    const candidate = routeMatch ? routeMatch[1] : raw;
    const normalized = normalizeSearchText(candidate);
    const report = reports.find(item => String(item.id) === candidate || normalizeSearchText(item.ticket_no) === normalized || normalizeSearchText(item.ticket_no).includes(normalized));
    if (report) {
        openGlobalSearchReport(report.id);
        return;
    }
    toast("Tiket tidak ditemukan pada data yang sedang dimuat.", "error");
}

function runQuickAction(action) {
    closeGlobalSearch();
    if (action === "add") openForm(); else if (action === "board") showTab("board"); else if (action === "actions") {
        showTab("dash");
        setTimeout(() => $("actionCenter")?.scrollIntoView({
            behavior: "smooth",
            block: "start"
        }), 100);
    } else if (action === "customers") showTab("cust"); else if (action === "finance") showTab("finance"); else if (action === "ticket") {
        showPrompt("Buka tiket atau QR", "Tempel nomor tiket, ID, atau link QR:", "Contoh: 010/RL/VIII/2026", "", openTicketFromCode);
    }
}

function initGlobalSearch() {
    if ($("globalSearchPalette")) return;
    const palette = document.createElement("div");
    palette.id = "globalSearchPalette";
    palette.className = "command-palette-backdrop";
    palette.setAttribute("aria-hidden", "true");
    palette.innerHTML = `<section class="command-palette" role="dialog" aria-modal="true" aria-labelledby="globalSearchTitle"><div class="command-search-row"><span>${productivityIcon("search")}</span><input id="globalSearchInput" autocomplete="off" placeholder="Cari tiket, pelanggan, WhatsApp, perangkat…" aria-label="Pencarian global"><button type="button" onclick="closeGlobalSearch()" aria-label="Tutup">${productivityIcon("close")}</button></div><div class="command-title-row"><div><span class="dashboard-kicker">Navigasi cepat</span><h2 id="globalSearchTitle">Cari dan buka apa pun</h2></div><kbd>Ctrl K</kbd></div><div id="globalSearchResults" class="command-results"></div><footer><span><kbd>↑</kbd><kbd>↓</kbd> pilih</span><span><kbd>Enter</kbd> buka</span><span><kbd>Esc</kbd> tutup</span></footer></section>`;
    palette.addEventListener("click", event => {
        if (event.target === palette) closeGlobalSearch();
    });
    document.body.appendChild(palette);
    $("globalSearchInput").addEventListener("input", () => {
        commandSelection = 0;
        renderGlobalSearch();
    });
    $("globalSearchInput").addEventListener("keydown", handleGlobalSearchKey);
    const actions = document.querySelector("#navMenu .navactions");
    if (actions) {
        const button = document.createElement("button");
        button.id = "globalSearchBtn";
        button.className = "btn small secondary global-search-button";
        button.type = "button";
        button.innerHTML = `${productivityIcon("search")}<span>Cari</span><kbd>⌘K</kbd>`;
        button.onclick = () => openGlobalSearch();
        actions.insertBefore(button, actions.firstChild);
    }
}

function directRange(children, startNode, endNode) {
    const start = children.indexOf(startNode);
    const end = endNode ? children.indexOf(endNode) : children.length;
    if (start < 0 || end < 0) return [];
    return children.slice(start, end);
}

function initReportWizard() {
    if (reportWizardInitialized) return;
    const modal = document.querySelector("#formModal > .modal");
    if (!modal) return;
    const actions = [ ...modal.children ].find(child => child.classList && child.classList.contains("actions") && child.querySelector("#saveBtn"));
    const headers = [ ...modal.children ].filter(child => child.classList && child.classList.contains("fs-h"));
    if (!actions || headers.length < 7) return;
    const [infoHeader, deviceHeader, levelHeader, slaHeader, workHeader, costHeader, docsHeader] = headers;
    const children = [ ...modal.children ];
    const tasks = $("f_tasks");
    const tasksLabel = tasks ? tasks.previousElementSibling : null;
    const editWrap = $("editActWrap");
    const groups = [ directRange(children, infoHeader, deviceHeader), directRange(children, deviceHeader, slaHeader), directRange(children, slaHeader, workHeader).concat([ tasksLabel, tasks ].filter(Boolean)), directRange(children, workHeader, costHeader), directRange(children, costHeader, docsHeader).filter(node => node !== tasksLabel && node !== tasks), directRange(children, docsHeader, actions) ];
    const header = document.createElement("div");
    header.id = "reportWizardHeader";
    header.className = "report-wizard-header";
    header.innerHTML = `<div class="wizard-heading"><div><span class="dashboard-kicker">Form bertahap</span><h3>Lengkapi laporan servis</h3></div><span id="wizardDraftStatus" class="wizard-draft-status">Autosave aktif</span></div><div class="wizard-progress" role="tablist">${REPORT_WIZARD_STEPS.map((step, index) => `<button type="button" role="tab" data-wizard-index="${index}" onclick="setReportWizardStep(${index})"><span>${index + 1}</span><small>${esc(step.short)}</small></button>`).join("")}</div><div id="reportDraftBanner" class="report-draft-banner" style="display:none"></div>`;
    modal.insertBefore(header, infoHeader);
    groups.forEach((nodes, index) => {
        const section = document.createElement("section");
        section.id = `reportWizardStep-${index}`;
        section.className = "report-wizard-step";
        section.dataset.step = String(index);
        modal.insertBefore(section, actions);
        nodes.filter(Boolean).forEach(node => section.appendChild(node));
    });
    const review = document.createElement("section");
    review.id = "reportWizardStep-6";
    review.className = "report-wizard-step wizard-review-step";
    review.dataset.step = "6";
    review.innerHTML = '<div id="reportWizardReview"></div>';
    modal.insertBefore(review, actions);
    const nav = document.createElement("div");
    nav.id = "reportWizardNav";
    nav.className = "report-wizard-nav";
    nav.innerHTML = `<button id="wizardBackBtn" class="btn secondary" type="button" onclick="moveReportWizard(-1)">Kembali</button><span id="wizardStepLabel"></span><button id="wizardNextBtn" class="btn" type="button" onclick="moveReportWizard(1)">Lanjut</button>`;
    modal.insertBefore(nav, actions);
    actions.id = "reportFormActions";
    reportWizardInitialized = true;
    setReportWizardStep(0, true);
}

function validateReportWizardStep(step) {
    if (step === 1) {
        if (!$("f_customer").value.trim()) {
            toast("Nama pelanggan wajib diisi sebelum melanjutkan.", "error");
            $("f_customer").focus();
            return false;
        }
        if (!$("f_phone").value.trim()) {
            toast("Nomor WhatsApp disarankan untuk komunikasi pelanggan.", "error");
            $("f_phone").focus();
            return false;
        }
    }
    if (step === 1 && typeof autoDeviceName === "function" && !String(autoDeviceName() || "").trim()) {
        toast("Lengkapi nama atau identitas perangkat.", "error");
        return false;
    }
    return true;
}

function setReportWizardStep(index, skipValidation) {
    initReportWizard();
    const target = Math.max(0, Math.min(Number(index) || 0, REPORT_WIZARD_STEPS.length - 1));
    if (!skipValidation && target > reportWizardStep && !validateReportWizardStep(reportWizardStep)) return;
    reportWizardStep = target;
    document.querySelectorAll(".report-wizard-step").forEach(section => {
        section.hidden = Number(section.dataset.step) !== target;
    });
    document.querySelectorAll(".wizard-progress button").forEach(button => {
        const step = Number(button.dataset.wizardIndex);
        button.classList.toggle("active", step === target);
        button.classList.toggle("complete", step < target);
        button.setAttribute("aria-selected", step === target ? "true" : "false");
    });
    const back = $("wizardBackBtn");
    const next = $("wizardNextBtn");
    const save = $("saveBtn");
    if (back) back.disabled = target === 0;
    if (next) next.style.display = target === REPORT_WIZARD_STEPS.length - 1 ? "none" : "";
    if (save) save.style.display = target === REPORT_WIZARD_STEPS.length - 1 ? "" : "none";
    if ($("wizardStepLabel")) $("wizardStepLabel").textContent = `${target + 1} / ${REPORT_WIZARD_STEPS.length} — ${REPORT_WIZARD_STEPS[target].label}`;
    if (target === REPORT_WIZARD_STEPS.length - 1) renderReportWizardReview();
    const overlay = $("formModal");
    if (overlay) overlay.scrollTop = 0;
    saveReportDraftSoon();
}

function moveReportWizard(delta) {
    setReportWizardStep(reportWizardStep + Number(delta || 0));
}

function wizardReviewItem(label, value, wide) {
    return `<div class="wizard-review-item ${wide ? "wide" : ""}"><span>${esc(label)}</span><strong>${esc(value || "-")}</strong></div>`;
}

function renderReportWizardReview() {
    const root = $("reportWizardReview");
    if (!root) return;
    const device = typeof autoDeviceName === "function" ? autoDeviceName() : "";
    const components = typeof getSelectedComps === "function" ? getSelectedComps() : [];
    const beforeCount = Array.isArray(formMedia.before) ? formMedia.before.length : 0;
    const afterCount = Array.isArray(formMedia.after) ? formMedia.after.length : 0;
    const fee = typeof _computeFee === "function" ? _computeFee() : 0;
    root.innerHTML = `<div class="wizard-review-head"><span class="dashboard-kicker">Langkah terakhir</span><h3>Periksa sebelum menyimpan</h3><p>Pastikan identitas pelanggan, perangkat, biaya, dan dokumentasi sudah benar.</p></div><div class="wizard-review-grid">${wizardReviewItem("No. tiket", $("f_ticket")?.value)}${wizardReviewItem("Jenis servis", $("f_jobtype")?.value)}${wizardReviewItem("Pelanggan", $("f_customer")?.value)}${wizardReviewItem("WhatsApp", $("f_phone")?.value)}${wizardReviewItem("Perangkat", device)}${wizardReviewItem("Merek", $("f_brand")?.value)}${wizardReviewItem("Level", `Level ${$("f_level")?.value || 1}`)}${wizardReviewItem("Target SLA", $("f_sla_due")?.value ? new Date($("f_sla_due").value).toLocaleString("id-ID") : "-")}${wizardReviewItem("Biaya", typeof rp === "function" ? rp(fee) : String(fee))}${wizardReviewItem("Pembayaran", $("f_payment")?.value)}${wizardReviewItem("Komponen", components.join(", ") || "-", true)}${wizardReviewItem("Pekerjaan", $("f_tasks")?.value, true)}${wizardReviewItem("Dokumentasi", `${beforeCount} before • ${afterCount} after`, true)}</div><div class="wizard-review-note"><strong>Autosave aktif</strong><span>Draft dihapus otomatis setelah laporan berhasil disimpan.</span></div>`;
}

function reportDraftKey(reportId) {
    const store = typeof STORE_ID !== "undefined" && STORE_ID ? STORE_ID : "store";
    const user = typeof ME !== "undefined" && (ME.user_id || ME.email) ? ME.user_id || ME.email : "user";
    return `repairlog:draft:${store}:${user}:${reportId || "new"}`;
}

function captureReportDraft() {
    const modal = $("formModal");
    if (!modal) return null;
    const values = {};
    modal.querySelectorAll("input[id],select[id],textarea[id]").forEach(field => {
        if ([ "file", "button", "submit", "hidden" ].includes(field.type)) return;
        values[field.id] = field.type === "checkbox" || field.type === "radio" ? Boolean(field.checked) : field.value;
    });
    return {
        version: 2,
        reportId: reportWizardReportId,
        updatedAt: (new Date).toISOString(),
        step: reportWizardStep,
        values: values,
        components: typeof getSelectedComps === "function" ? getSelectedComps() : [],
        kelengkapan: typeof getKelengkapan === "function" ? getKelengkapan() : [],
        costItems: typeof costItemsState !== "undefined" && Array.isArray(costItemsState) ? costItemsState : [],
        media: {
            before: (formMedia.before || []).filter(item => item.url && !String(item.url).startsWith("data:") && !String(item.url).startsWith("blob:")),
            after: (formMedia.after || []).filter(item => item.url && !String(item.url).startsWith("data:") && !String(item.url).startsWith("blob:"))
        }
    };
}

function saveReportDraftSoon() {
    if (reportWizardRestoring || !$("formModal")?.classList.contains("open")) return;
    clearTimeout(reportDraftTimer);
    reportDraftTimer = setTimeout(saveActiveReportDraft, 650);
}

function saveActiveReportDraft() {
    if (reportWizardRestoring || !$("formModal")?.classList.contains("open")) return;
    const draft = captureReportDraft();
    if (!draft) return;
    try {
        localStorage.setItem(reportDraftKey(reportWizardReportId), JSON.stringify(draft));
        const status = $("wizardDraftStatus");
        if (status) status.textContent = `Draft tersimpan ${(new Date).toLocaleTimeString("id-ID", {
            hour: "2-digit",
            minute: "2-digit"
        })}`;
    } catch (error) {
        const status = $("wizardDraftStatus");
        if (status) status.textContent = "Draft gagal disimpan";
    }
}

function loadReportDraft(reportId) {
    try {
        return JSON.parse(localStorage.getItem(reportDraftKey(reportId)) || "null");
    } catch (error) {
        return null;
    }
}

function clearActiveReportDraft() {
    clearTimeout(reportDraftTimer);
    try {
        localStorage.removeItem(reportDraftKey(reportWizardReportId));
    } catch (error) {}
    const banner = $("reportDraftBanner");
    if (banner) banner.style.display = "none";
}

function discardReportDraft() {
    clearActiveReportDraft();
    toast("Draft dihapus.", "success");
}

function applyDraftValues(draft) {
    if (!draft || !draft.values) return;
    reportWizardRestoring = true;
    const prefill = id => {
        const field = $(id);
        if (field && Object.prototype.hasOwnProperty.call(draft.values, id)) field.value = draft.values[id];
    };
    prefill("f_jobtype");
    prefill("f_devtype");
    if (typeof onJobTypeChange === "function") onJobTypeChange();
    if (typeof onDevTypeChange === "function") onDevTypeChange();
    setTimeout(() => {
        Object.entries(draft.values).forEach(([id, value]) => {
            const field = $(id);
            if (!field) return;
            if (field.type === "checkbox" || field.type === "radio") field.checked = Boolean(value); else field.value = value == null ? "" : value;
        });
        if (Array.isArray(draft.components) && typeof setComps === "function") {
            setComps(draft.components);
        }
        if (Array.isArray(draft.kelengkapan) && typeof buildKelengkapan === "function") {
            buildKelengkapan(draft.kelengkapan, ($("f_jobtype")?.value || "Service") === "Garansi");
        }
        if (Array.isArray(draft.costItems) && typeof costItemsState !== "undefined") {
            costItemsState = draft.costItems;
            if (typeof renderCostItems === "function") renderCostItems();
        }
        if (draft.media) {
            formMedia.before = Array.isArray(draft.media.before) ? draft.media.before : [];
            formMedia.after = Array.isArray(draft.media.after) ? draft.media.after : [];
            if (typeof renderThumbs === "function") {
                renderThumbs("before");
                renderThumbs("after");
            }
        }
        if (typeof toggleDp === "function") toggleDp();
        if (typeof togglePaySplit === "function") togglePaySplit();
        if (typeof refreshSlaSuggestion === "function") refreshSlaSuggestion(false);
        setReportWizardStep(Number(draft.step) || 0, true);
        reportWizardRestoring = false;
        formDirty = true;
        const banner = $("reportDraftBanner");
        if (banner) banner.style.display = "none";
        toast("Draft berhasil dipulihkan.", "success");
    }, 60);
}

function restoreReportDraft() {
    const draft = loadReportDraft(reportWizardReportId);
    if (draft) applyDraftValues(draft);
}

function renderReportDraftBanner() {
    const banner = $("reportDraftBanner");
    if (!banner) return;
    const draft = loadReportDraft(reportWizardReportId);
    if (!draft || !draft.updatedAt) {
        banner.style.display = "none";
        return;
    }
    const time = new Date(draft.updatedAt);
    banner.style.display = "flex";
    banner.innerHTML = `<div><strong>Draft ditemukan</strong><span>Terakhir disimpan ${time.toLocaleString("id-ID")}. Foto lokal yang belum diunggah tidak termasuk.</span></div><div><button class="btn small secondary" type="button" onclick="discardReportDraft()">Hapus</button><button class="btn small" type="button" onclick="restoreReportDraft()">Pulihkan</button></div>`;
}

function prepareReportWizard(reportId) {
    initReportWizard();
    reportWizardReportId = reportId || "new";
    reportWizardStep = 0;
    setReportWizardStep(0, true);
    renderReportDraftBanner();
    const status = $("wizardDraftStatus");
    if (status) status.textContent = "Autosave aktif";
}

function openFormAtWizardStep(id, step) {
    openForm(id);
    setTimeout(() => setReportWizardStep(step, true), 100);
}

function initMobileBottomNav() {
    if ($("mobileBottomNav")) return;
    const nav = document.createElement("nav");
    nav.id = "mobileBottomNav";
    nav.className = "mobile-bottom-nav";
    nav.setAttribute("aria-label", "Navigasi mobile");
    nav.innerHTML = `<button type="button" data-mobile-tab="dash" onclick="showTab('dash')">${productivityIcon("home")}<span>Beranda</span></button><button type="button" data-mobile-tab="board" onclick="showTab('board')">${productivityIcon("board")}<span>Papan</span></button><button type="button" class="mobile-add" onclick="openForm()">${productivityIcon("plus")}<span>Tambah</span></button><button type="button" data-mobile-tab="cust" onclick="showTab('cust')">${productivityIcon("users")}<span>Pelanggan</span></button><button type="button" onclick="toggleNavMenu()">${productivityIcon("more")}<span>Lainnya</span></button>`;
    document.body.appendChild(nav);
    syncMobileNav("dash");
    syncMobileNavVisibility();
}

function syncMobileNav(tab) {
    document.querySelectorAll("#mobileBottomNav [data-mobile-tab]").forEach(button => {
        button.classList.toggle("active", button.dataset.mobileTab === tab);
    });
}

function syncMobileNavVisibility() {
    const nav = $("mobileBottomNav");
    const header = $("appHeader");
    if (!nav || !header) return;
    const publicRoute = /^#\/(?:c|t|g|a)\//i.test(location.hash || "");
    const appVisible = getComputedStyle(header).display !== "none";
    const modalOpen = Boolean(document.querySelector(".modal-bg.open"));
    nav.classList.toggle("is-hidden", publicRoute || !appVisible || modalOpen);
    document.body.classList.toggle("has-mobile-nav", !publicRoute && appVisible && !modalOpen);
}

function renderMobileTicketActions(reportId) {
    const report = reports.find(item => String(item.id) === String(reportId));
    const container = $("detailContent");
    if (!report || !container) return;
    const old = $("mobileTicketActions");
    if (old) old.remove();
    const actions = document.createElement("div");
    actions.id = "mobileTicketActions";
    actions.className = "mobile-ticket-actions";
    actions.innerHTML = `<button type="button" onclick="${report.customer_phone ? `focusServiceToolCard('whatsapp')` : `openFormAtWizardStep('${report.id}',0)`}"><span>WA</span><small>Hubungi</small></button><button type="button" onclick="focusServiceToolCard('quality')"><span>QC</span><small>Periksa</small></button><button type="button" onclick="openFormAtWizardStep('${report.id}',5)"><span>+</span><small>Foto</small></button><button type="button" onclick="openFormAtWizardStep('${report.id}',2)"><span>≡</span><small>Catatan</small></button><button type="button" onclick="setStatus('${report.id}','Selesai')"><span>✓</span><small>Selesai</small></button>`;
    const finalActions = [ ...container.children ].reverse().find(element => element.classList && element.classList.contains("actions"));
    if (finalActions) container.insertBefore(actions, finalActions); else container.appendChild(actions);
}

function initProductivityFeatures() {
    initGlobalSearch();
    initReportWizard();
    initMobileBottomNav();
    const form = $("formModal");
    if (form) {
        form.addEventListener("input", saveReportDraftSoon);
        form.addEventListener("change", saveReportDraftSoon);
    }
    document.addEventListener("keydown", event => {
        if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === "k") {
            event.preventDefault();
            const palette = $("globalSearchPalette");
            if (palette && palette.classList.contains("open")) closeGlobalSearch(); else openGlobalSearch();
        }
        if (event.key === "Escape" && $("globalSearchPalette")?.classList.contains("open")) closeGlobalSearch();
    });
    const header = $("appHeader");
    if (header) new MutationObserver(syncMobileNavVisibility).observe(header, {
        attributes: true,
        attributeFilter: [ "style", "class" ]
    });
    const modalObserver = new MutationObserver(syncMobileNavVisibility);
    document.querySelectorAll(".modal-bg").forEach(modal => modalObserver.observe(modal, {
        attributes: true,
        attributeFilter: [ "class" ]
    }));
    window.addEventListener("hashchange", syncMobileNavVisibility);
    window.addEventListener("resize", syncMobileNavVisibility);
}

initProductivityFeatures();

;

